    if (secondClose === -1) return undefined
    const rawLabel = text.slice(close + 2, secondClose)
    const label = normalizeLabel(rawLabel === '' ? inner : rawLabel)
    const url = definitions.get(label)
    if (url === undefined) return undefined
    return { url, inner, next: secondClose + 1 }
  }
  return undefined
