 * @param {string} text - the raw inline text.
 * @param {Map<string, string>} [definitions] - normalized label to url, for reference links.
 * @returns {string} the HTML.
 */
export function renderInline(text, definitions = new Map()) {
  let out = ''
  let index = 0
  while (index < text.length) {
    const character = text[index]
