      out += escapeText(text[index + 1])
      index += 2
      continue
    }
    if (character === '`') {
      const end = text.indexOf('`', index + 1)
      if (end !== -1) {
        out += `<code>${escapeText(text.slice(index + 1, end))}</code>`
        index = end + 1
        continue
