/** The command: `html`, `outline`, and `defs`, each over the document on standard input, with an optional definitions file. */

import { readFileSync } from 'node:fs'
import { BlockError, headings, parse, render, splitLines } from './block.js'
import { readDefinition } from './definitions.js'

const MODES = ['html', 'outline', 'defs']
const USAGE = 'usage: cli.js html|outline|defs [<definitions>]'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/**
 * Read a definitions file: one definition per line, blank lines and `#` comments ignored.
 * @param {string} path - the file to read.
 * @returns {Map<string, string>} normalized label to url.
 */
function readDefinitionsFile(path) {
  let text
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    fail(`cannot read definitions ${path}`)
  }
  const lines = splitLines(text)
  const definitions = new Map()
  for (let index = 0; index < lines.length; index += 1) {
    const line = index + 1
    const trimmed = lines[index].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const definition = readDefinition(trimmed)
    if (definition === undefined) fail(`${path}: line ${line}: expected [label]: <url>`)
    if (definitions.has(definition.label)) fail(`${path}: line ${line}: label ${definition.label} is defined twice`)
    definitions.set(definition.label, definition.url)
  }
  return definitions
}

const argv = process.argv.slice(2)
const mode = argv[0]
if (!MODES.includes(mode) || argv.length < 1 || argv.length > 2) fail(USAGE)

const input = readFileSync(0, 'utf8')

const fileDefinitions = argv.length === 2 ? readDefinitionsFile(argv[1]) : new Map()

let blocks
let documentDefinitions
try {
  ;({ blocks, definitions: documentDefinitions } = parse(splitLines(input), fileDefinitions))
} catch (error) {
  if (!(error instanceof BlockError)) throw error
  fail(`line ${error.line}: ${error.message}`)
}

if (mode === 'html') {
  const definitions = new Map([...fileDefinitions, ...documentDefinitions])
  process.stdout.write(render(blocks, definitions))
} else if (mode === 'outline') {
  process.stdout.write(headings(blocks).map(one => `${one.level} ${one.text}\n`).join(''))
} else {
  const entries = [
    ...[...fileDefinitions].map(([label, url]) => ({ label, url, source: 'file' })),
    ...[...documentDefinitions].map(([label, url]) => ({ label, url, source: 'document' })),
  ].sort((a, b) => (a.label < b.label ? -1 : a.label > b.label ? 1 : 0))
  process.stdout.write(entries.map(one => `${one.label} ${one.url} ${one.source}\n`).join(''))
  process.stdout.write(`total ${entries.length}\n`)
}
"}

